export async function handleStart(ctx) {
    const welcomeMessage = `👋 <b>أهلاً بك في بوت تحويل استكرات تليجرام إلى واتساب!</b> 🎨

هذا البوت مخصص لتحويل أي استكر أو حزمة تليجرام كاملة إلى حزم واتساب رسمية تلقائياً.

---
⚡ <b>طريقة الاستخدام:</b>

1️⃣ <b>تحويل الحزمة كاملة تلقائياً:</b>
أرسل أي استكر من الحزمة، أو أرسل رابط الحزمة، وسيقوم البوت تلقائياً بما يلي:
• سحب الحزمة كاملة وإعادة تسميتها باسم البوت <b>@stickermakerusbot</b>.
• تقسيم الحزم الكبيرة إلى أجزاء (حد أقصى 30 استكر لكل حزمة وفق معايير واتساب).
• إرسال ملفات <b>.wastickers</b> مباشرة دون الحاجة لملفات zip.

2️⃣ <b>إضافة الاستكرات إلى واتساب بنقرة واحدة:</b>
افتح ملف <b>.wastickers</b> باستخدام تطبيقنا المخصص <b>Sticker Maker US</b> أو تطبيق <b>Sticker Maker</b>، واضغط <b>إضافة إلى WhatsApp</b>!

---
ℹ️ للمزيد من الشرح وتفاصيل التطبيق: /help`;
    await ctx.reply(welcomeMessage, { parse_mode: 'HTML' });
}
export async function handleHelp(ctx) {
    const helpMessage = `📖 <b>دليل إضافة الاستكرات إلى واتساب:</b>

📱 <b>الخطوات على الهاتف:</b>
1. عندما يرسل لك البوت ملف بصيغة <b>.wastickers</b>، اضغط عليه في تليجرام.
2. اختر <b>فتح بواسطة (Open with)</b> ثم اختر تطبيق <b>Sticker Maker US</b> (برنامج البوت المخصص) أو <b>Sticker Maker</b>.
3. ستفتح الحزمة مباشرة في التطبيق، اضغط على زر: <b>إضافة إلى WhatsApp</b> وستظهر الاستكرات فوراً في محادثاتك! 🎉

⚙️ <b>المعايير المطبقة تلقائياً:</b>
✅ تقسيم تلقائي بحد أقصى 30 استكر لكل حزمة (وفق الحد الأقصى الرسمي لواتساب).
✅ الأبعاد: 512×512 بكسل بدقة شفافة.
✅ الحجم: متوافق 100% مع شروط واتساب للثابت والمتحرك.
✅ توثيق الحزمة باسم <b>@stickermakerusbot</b>.

لأي استفسار أو بدء التحويل، أرسل أي استكر الآن!`;
    await ctx.reply(helpMessage, { parse_mode: 'HTML' });
}
